// ----------------------------------------------------------------------
export interface CatalogHardcodedRefs {
  /**
   * One entry per distinct `domain.object_id` in a repo. A service call never appears here: the
   * extraction classifies each reference structurally and only entity references enter the
   * audit.
   */
  refs: CatalogHardcodedRefsEntry[];
}

export interface CatalogHardcodedRefsEntry {
  /**
   * The justification, when the reference is one of the fixed things rather than a slot. A
   * closed set, deliberately heterogeneous because the property it needs is single: these are
   * the fixed targets a reference may name instead of a slot.
   */
  constant: "device_id" | "device_tracker" | "person" | "sun" | "time" | null;
  /**
   * The literal as the source spells it. A fact about someone's naming scheme, committed for
   * all four repos including the two that grant nothing, because the hardcoding audit cannot be
   * complete without it. Excluded from the door in the other direction: a service name is
   * spelled the same way, so which references enter here is decided by the extraction's
   * structural classifier and not by this pattern.
   */
  entity_ref: string;
  /**
   * The repo's naming-convention label. A slug so it cannot carry a sentence, and drawn from a
   * fixed set the extraction fixes when it sees the data.
   */
  naming_convention: string;
  /**
   * The repo the reference was found in. A slug and not free text: repo handles are lower-case,
   * and a slug cannot hold a sentence.
   */
  repo: string;
  /**
   * Inferred from the reference's domain, so the same concept can be compared across repos. A
   * closed set, and the inference is what task 5.3 uses to place a reference against the room
   * map.
   */
  scope: "room" | "house";
  /**
   * The slot this reference maps to, or null when the reference resolves to a `constant`
   * instead. The closed set is `catalog/slots.yaml` itself, so the field is the product's own
   * vocabulary rather than a copied pattern -- the same rule the raw record's `slots` field
   * follows. Exactly one of `slot` and `constant` is non-null, which `hardcoded_entry_one_of`
   * states above and `check_slots` enforces by naming the reference and its repo.
   */
  slot: "ambient_light_sensor" | "climate_zone" | "cover" | "door_contact" | "fan" | "humidity_sensor" | "leak_sensor" | "light_group" | "lock" | "media_player" | "motion_sensor" | "scene_selector" | "temperature_sensor" | "vacuum" | null;
}

