export type CatalogInventoryArtifactClass = "package" | "automation" | "script" | "scene" | "helper" | "template" | "blueprint" | "dashboard" | "custom_integration" | "other";

export interface CatalogInventoryCounts {
  excluded: number;
  selected: number;
  tracked: number;
}

export interface CatalogInventoryFile {
  /**
   * The class of the deciding rule when it selected, and null when it excluded. Recorded per
   * file rather than derived at read time, because the deciding rule's class is the file's
   * class and nothing infers it from the file's content.
   */
  class: unknown;
  /**
   * The parse error, when `parse` is `unparsed`. Non-null exactly there: an unparsed file keeps
   * its class, is recorded with the error that stopped it, and still counts in the class total.
   */
  error?: null;
  /**
   * A separate field from the class so that class counts still sum to the selected count when a
   * file will not parse.
   */
  parse: "parsed" | "unparsed" | "not_applicable";
  /** Repo-relative, exactly as `git ls-files` reports it. */
  path: string;
  /**
   * The `order` of the deciding rule, so the per-rule counts close over the same list they were
   * produced from.
   */
  rule: number;
  /** True when the deciding rule selected the file. */
  selected: boolean;
}

export interface CatalogInventoryRepo {
  /**
   * Class name to count. Keys are class names rather than a fixed shape, because a class with
   * no files is absent rather than zero and the check that reconciles the sum is what makes the
   * omission visible.
   */
  by_class: { [key: string]: number; };
  /** Parse outcome to count. */
  by_parse: { [key: string]: number; };
  /**
   * Rule `order` as a string to the counts that rule decided, so that a rule which decided
   * nothing is detectable by its absence from a list of every rule. Over every decided file and
   * not only the excluded ones: a select rule that decided files would otherwise be missing
   * from the map, and missing is exactly how a rule that decided nothing reads. `decided`
   * therefore sums to the repo's tracked count, which is what makes this map and the `files`
   * list demonstrably two views of one partition; `excluded` is carried beside it rather than
   * left to be derived, because the closure clause names the excluded count per deciding rule,
   * and a figure the reader has to reconstruct is not a figure that was reported.
   */
  by_rule: { [key: string]: CatalogInventoryRuleCounts; };
  counts: CatalogInventoryCounts;
  /**
   * Every tracked path, selected and excluded alike. The excluded ones are kept rather than
   * counted and dropped, because the requirement's closure is over the whole `git ls-files`
   * output and a list of only the survivors could not demonstrate it.
   */
  files: CatalogInventoryFile[];
  repo: string;
}

export interface CatalogInventoryRuleCounts {
  decided: number;
  excluded: number;
  selected: number;
}

