// ----------------------------------------------------------------------
// catalog/repos @ 1.0.0
// ----------------------------------------------------------------------
export interface CatalogRepos {
  repos: CatalogReposRepo[];
}

export interface CatalogReposRepo {
  author: string;
  /** The one thing this repo contributes that the others do not. */
  best_at: string;
  /**
   * Deliberately unordered. An earlier draft required the most characteristic style first,
   * which turned out to be a claim about the repo that nothing could check.
   */
  ha_style: "package" | "split-include" | "blueprint-driven" | "custom-integration" | "dashboard-strategy" | "appdaemon"[];
  /**
   * Checked against the repo's `.HA_VERSION` at curation time, not in CI: the clones are absent
   * from CI by design.
   */
  ha_version: string;
  name: string;
  purpose: string;
  repo_url: string;
  scale: string;
}

// ----------------------------------------------------------------------
// catalog/room_types @ 1.0.0
// ----------------------------------------------------------------------
export interface CatalogRoomTypes {
  /**
   * Slots that belong to the house. A house-scoped behaviour can require only slots named here,
   * and a room-scoped one only slots some room type provides.
   */
  house?: { /**
 * Resolved against `catalog/slots.yaml`; the membership rule is the validator's, because a JSON
 * Schema reference cannot reach into a YAML document's contents. The entry shape is the runtime
 * `slot` schema's own `name` property, referenced rather than restated.
 */ slots: string[]; };
  /**
   * The union of real rooms is not truncated by the corroboration rule: a type that exists in
   * only one repo is recorded with `default: false`, because the map has to be able to express
   * every real room even where only one house has one.
   */
  room_types: RoomType[];
}

// ----------------------------------------------------------------------
// catalog/rooms @ 1.0.0
// ----------------------------------------------------------------------
export interface CatalogRooms {
  rooms: CatalogRoomsRoom[];
}

export interface CatalogRoomsRoom {
  /**
   * The room as the repo spells it. Kept verbatim, including a non-English name: this is the
   * record of what exists, and normalising it here would destroy the evidence the room-type map
   * is derived from.
   */
  name: string;
  /**
   * Repo-relative paths of every selected file the room was read from, sorted. A list rather
   * than one path because a room is ordinarily spread across a package directory, a dashboard
   * and its helpers; every entry names the room and every selected file that names the room is
   * an entry, which `tools/catalog/rooms.py` re-derives and enforces.
   */
  paths: string[];
  /**
   * The repository's owner handle, lowercased, as `licenses.yaml` and `inventory.json` name it.
   * One record per room per repo, so a room two setups both have is two records and the
   * corroboration join counts two repos.
   */
  repo: string;
}

// ----------------------------------------------------------------------
// catalog/services @ 1.0.0
// ----------------------------------------------------------------------
export interface CatalogServices {
  /** One row per service the port can carry out, as the state it writes. */
  services: { /**
 * The `domain.service` a manifest's behaviour clause may name. The same shape the manifest
 * schema's own `services` pattern admits, repeated because the two are read by different
 * checkers and a row that could not be declared would be a row nothing reads.
 */ service: string; /**
 * The state the port writes on the entity this service acts through. Deliberately not
 * constrained to an enum here: the states are Home Assistant's, and the domain that owns each
 * is the authority on its spelling rather than this schema.
 */ state: string; }[];
}

export type CatalogServicesService = { /**
 * The `domain.service` a manifest's behaviour clause may name. The same shape the manifest
 * schema's own `services` pattern admits, repeated because the two are read by different
 * checkers and a row that could not be declared would be a row nothing reads.
 */ service: string; /**
 * The state the port writes on the entity this service acts through. Deliberately not
 * constrained to an enum here: the states are Home Assistant's, and the domain that owns each
 * is the authority on its spelling rather than this schema.
 */ state: string; };

// ----------------------------------------------------------------------
// catalog/slots @ 1.0.0
// ----------------------------------------------------------------------
export interface CatalogSlots {
  /**
   * Every multi-source slot carries examples from at least two different source repos: an
   * overlap across repos is the strongest signal that a slot belongs in the defaults, and a
   * single-repo slot does not have that signal. The cross-record rule is the validator's, not
   * the schema's.
   */
  slots: Slot[];
}

// ----------------------------------------------------------------------
// engine-api @ 1.0.0
// ----------------------------------------------------------------------
/** `engine-api` declares no shape of its own; the version alone is the artifact. */
export type EngineAPIVersion = Record<string, never>;

// ----------------------------------------------------------------------
// export-document @ 1.1.0
// ----------------------------------------------------------------------
export interface ExportDocument {
  /**
   * The selections in force: which room profile each room is on per axis, and the house profile
   * if one is active.
   */
  active?: ExportDocumentActive;
  /**
   * 1.0.0's flat binding list. Accepted for the migration and for the committed example; a full
   * backup writes `rooms` instead.
   */
  bindings?: ExportDocumentBinding[];
  exported_at?: string;
  format_version: string;
  house: string;
  house_scope?: { slots: string[]; };
  /**
   * The modes the house declares. Carried so a backup restores the mode definitions a profile
   * activates, not only the profile.
   */
  modes?: ExportDocumentMode[];
  /**
   * Every profile the house holds, room and house kinds alike. Defined inline rather than
   * referenced, because a validator pointed at this file alone resolves no other file.
   */
  profiles?: ExportDocumentProfile[];
  /**
   * The house's rooms, each with its name, type and bindings. This is what a full backup writes
   * and what the migration producing a current document fills.
   */
  rooms?: ExportDocumentRoom[];
}

export interface ExportDocumentActive {
  house_profile?: null;
  rooms?: { [key: string]: { [key: string]: string; }; };
}

export interface ExportDocumentBinding {
  entity_id: string;
  registry_id: string;
  room: string;
  slot: string;
}

export interface ExportDocumentMode {
  description: string;
  exclusive_group?: string;
  name: string;
}

export interface ExportDocumentProfile {
  axis?: string;
  deltas?: { [key: string]: unknown; };
  description: string;
  enabled_behaviours?: string[];
  kind: "room" | "house";
  modes?: string[];
  name: string;
  selections?: { [key: string]: { [key: string]: string; }; };
}

export interface ExportDocumentRoom {
  bindings: { [key: string]: ExportDocumentRoomBinding; };
  id: string;
  name: string;
  type: string;
}

export interface ExportDocumentRoomBinding {
  entity_id: string;
  registry_id: string;
}

// ----------------------------------------------------------------------
// house @ 1.0.0
// ----------------------------------------------------------------------
export interface House {
  /**
   * Slots that belong to the house rather than a room, so a house-scoped behaviour is not
   * forced through a room type it has nothing to do with.
   */
  house_scope: { /** Slot names made available at house scope. */ slots: string[]; };
  name: string;
  rooms: HouseRoom[];
}

export interface HouseBinding {
  entity_id: string;
  /** The device registry id, when the binding is a device rather than a bare entity. */
  registry_id?: string;
}

export interface HouseRoom {
  /**
   * Slot name to binding. A slot the type provides may be absent, which is how an optional slot
   * is left unbound.
   */
  bindings: { [key: string]: HouseBinding; };
  id: string;
  name: string;
  /** The name of a room type. Resolved against room_types.yaml. */
  type: string;
}

// ----------------------------------------------------------------------
// mode @ 1.0.0
// ----------------------------------------------------------------------
export interface Mode {
  description: string;
  /**
   * Modes sharing a group are mutually exclusive, which is how 'only one of these at a time' is
   * expressed without a rule that enumerates pairs.
   */
  exclusive_group?: string;
  name: string;
}

// ----------------------------------------------------------------------
// pack-manifest @ 1.4.0
// ----------------------------------------------------------------------
export interface PackManifest {
  /**
   * The behaviours the pack declares, each named by a trigger, a condition and an action drawn
   * from `behavior-vocabulary`'s published axes. The terms are referenced, not restated, so the
   * pack cannot use a behaviour term the vocabulary does not carry. Required for the kinds that
   * do something in a room; a template declares what a room has rather than what it does, so
   * the per-kind conditionals below forbid it there.
   */
  behaviours?: PackManifestBehaviour[];
  /**
   * Packs this pack must not share a house with, each a name and a range it must not satisfy.
   * Checked in both directions -- from the arriving pack to the installed set and from each
   * installed pack to the arriving one -- because a conflict one pack states and the other does
   * not is still a conflict.
   */
  conflicts?: PackManifestReference[];
  /**
   * Installed packs this pack needs, each an installed pack's name and a semver range its
   * version must satisfy. Resolved against the house's installed set and never against the
   * repository, because what a pack may rely on is what the house actually holds.
   */
  dependencies?: PackManifestReference[];
  /**
   * The corpus row ids this pack reproduces expression from, read against
   * `catalog/behaviors.yaml`. Carried by a derived pack and forbidden on a hand-written one,
   * because a file a person wrote reproduces no row's expression -- provenance that lives only
   * in a report on the machine that ran the derivation stops travelling the moment the pack is
   * copied, and an empty list is not a derivation.
   */
  derives_from?: string[];
  description: string;
  /**
   * The engine API range this pack is written for, as a semver range: comparators over dotted
   * versions, joined by whitespace or `||`. It supersedes `min_engine_version`, which pinned a
   * lower bound and could not express an upper one, so a pack broken by the next major version
   * could not say so. Checked against the engine's own declared API version, which is published
   * in an artifact of its own rather than read from `pyproject.toml` -- whose `version` is
   * `0.0.0` and moves for packaging reasons, which would make every range a lie.
   */
  engine_api: string;
  /**
   * A default string for every user-visible name the pack declares, with locale overrides
   * resolved over it. Required rather than optional, because a name with no default is a name
   * some locale cannot render.
   */
  i18n: PackManifestI18n;
  /**
   * The kind of pack this is. 1.1.0 carried this as a pattern and said why in its own words --
   * "A pattern and not an enum because no corpus of packs exists to derive a closed set of
   * kinds from, and inventing one here would freeze..." -- and 1.2.0 ships that corpus, so the
   * closure is this version's to make.
   */
  kind: "module" | "room-template" | "behavior" | "profile-set" | "house-template";
  /**
   * The pack's licence, as one of the codes `schemas/catalog/licenses.json` publishes -- the
   * same codes `catalog/behaviors.yaml`'s rows already speak, so a manifest that said `MIT`
   * would be a third spelling of one fact. Each code carries its SPDX identifier in that
   * artifact rather than in a second list here.
   */
  license: "public_domain" | "mit" | "apache_2_0" | "cc_by_nc_sa" | "no_licence";
  name: string;
  /**
   * Slots the pack can use but does not require, so a house missing one still installs it.
   * Separate from `requires_slots` rather than folded in, because the two say different things
   * about the house the pack lands in and one list cannot carry both.
   */
  optional_slots?: string[];
  /**
   * The settings this pack offers a person, each a small typed declaration and never a
   * free-form schema. A module knows what it is *for* and what a person might reasonably want
   * to change about it -- how long the fridge door may stand open, whether the fan runs at all
   * after dark -- and until this clause existed there was nowhere to say so: a pack could
   * declare what it does and not one number about how. The declaration is deliberately narrow
   * rather than a nested JSON Schema, because the panel already renders a schema and the
   * interesting question is not what *can* be expressed but what the *engine* will act on.
   * Every option resolves under `module.<pack>.<key>` through the same layered resolver as
   * every other tunable (`engine/config.py`), so a house and a room may each set one and the
   * pack's `default` is the bottom of the stack. **An option is only worth declaring if
   * something reads it**: `for` on a behaviour names a duration option and is how the
   * declarative interpreter acts on one, and a boolean option's honest use is gated the same
   * way. Declaring an option nothing reads is the defect this description exists to warn
   * against, because the panel will render a control for it and the control will do nothing.
   */
  options?: PackManifestOption[];
  /**
   * Every entry carries the artifact class it confers, because the class-pinning rule is what
   * stops a pack smuggling an unpinnable artifact past the licence gate by calling it a helper.
   */
  provides: PackManifestProvided[];
  /**
   * Slot names, resolved against slots.yaml. A pack that names a slot no slot file defines is a
   * pack that cannot be installed anywhere. Required for the kinds that are plugged into a room
   * and forbidden nowhere; the per-kind conditionals below say which kinds must carry it. The
   * list may be empty, and an empty list is a statement rather than a hole: a pack that acts
   * through a service and no placeholder -- a notification, an alarm panel, a siren -- is
   * plugged into a room and needs nothing of it. The home's own state used to be the slot that
   * made such packs non-empty, and it is the engine's variable rather than a device anybody
   * binds, so a corpus row that required it now requires nothing and says so.
   */
  requires_slots?: string[];
  /**
   * The slots this pack brings with it. A pack may need a device no catalog slot names -- a
   * fridge's door, a freezer's -- and the vocabulary is grown by the modules rather than by a
   * publisher's release, so the pack that needs the reading declares it and fixes the domains a
   * binding may use. A declared name says what the device is: two packs naming the same slot
   * share the one device, so the name is the whole of the disambiguation -- there is no second
   * sentence to fall back on, which is why a name that could mean two devices is the defect
   * this clause exists to refuse.
   */
  slots?: PackManifestDeclaredSlot[];
  version: string;
}

export type PackManifestDerivesFrom = string;

export type PackManifestOptionalSlot = string;

export type PackManifestRequiresSlot = string;

export interface PackManifestBehaviour {
  /**
   * The action block kind the behaviour ends in. Required, because a behaviour with no action
   * does nothing and the action is the one axis every behaviour the extraction found carries.
   */
  action: BehaviourVocabularyAction;
  /** A condition block kind, resolved against the published vocabulary rather than restated here. */
  condition?: BehaviourVocabularyCondition;
  /**
   * The name of a `duration` option this behaviour waits out: it proposes only once the reading
   * `match` names has *held* for that long. The run-on period, and the second half of what
   * `match` needs to be useful -- `match: [open]` says the door is open now, and `for:
   * open_minutes` says it has been open for five minutes, which is the difference between an
   * alarm and a nuisance. It names an option rather than carrying a literal duration because
   * *how long* is exactly the sort of number a person wants to change and a manifest author
   * cannot guess: the value resolves under `module.<pack>.<key>` and the panel draws a field
   * for it. A name that is not a declared `duration` option is refused when the manifest is
   * validated -- the clause is meaningless without one, and the check happens where the option
   * list is readable rather than at evaluation, where the reading would silently never hold.
   */
  for?: string;
  /**
   * The readings this behaviour acts on: it proposes only when the entity it acts through
   * currently reads one of these. This is the *value* beside the `condition` kind --
   * `condition: state` names the kind of test and `match` names what the test is for -- and the
   * pair is what lets a behaviour dispatch rather than fire blind: a vacuum pack starts a clean
   * only when the vacuum reads `docked`, and sends it home only when it reads `cleaning`. A
   * string and not an object, because the comparison is always equality against a literal state
   * name; anything richer would be the expression language `catalog/pack-policy.yaml` forbids.
   * Omitted means 'whatever the slot reads', which is 1.2.0's behaviour and is still a legal
   * pack.
   */
  match?: string[];
  /**
   * The house mode this behaviour enters when it acts, as the frozen mode schema spells a mode
   * name (`schemas/mode/1.0.0.json` lower-cases them). The *value* beside a `service` action
   * for a behaviour whose act is not a device write: the Bedtime button's second clause is the
   * house entering Sleep, and nothing in 1.2.0 could say so -- which is why the pack could not
   * be written. Only the name's *shape* is checked here, and deliberately: a manifest does not
   * know which house it will land in, so the name meets a house for the first time when the
   * behaviour is evaluated. A name the house does not declare is then refused rather than
   * raised -- the request is recorded as a `mode_request` whose `taken` is `false`, the rest of
   * the behaviour still runs, and a tick survives both a pack installed into a house whose
   * modes changed under it and a hand-edited manifest.
   */
  mode?: string;
  name?: string;
  /**
   * What arbitration ranks this behaviour by when two behaviours propose for one entity in one
   * tick. A clause of the behaviour rather than of the pack, because one pack's two behaviours
   * may compete at different ranks. Omission takes the default `catalog/pack-policy.yaml`
   * publishes, so a manifest may state what it means and is not required to restate what the
   * default already says.
   */
  priority?: number;
  /**
   * How often this behaviour is evaluated: once per room it is installed into, or once for the
   * whole house. The corpus records exactly this word per row, and the engine's
   * `BehaviourScope` is that word rather than a translation of it, so the clause is the
   * corpus's own and not a second vocabulary. A behaviour whose acts are about one space -- a
   * room's lights, a room's fan -- is `room`, which is the default and is what 1.2.0 could
   * express. A behaviour about the house as a whole -- the alarm, the doors, the energy meter,
   * the vacuum that cleans everything -- is `house`, and it is evaluated once with the house's
   * own bindings rather than once per room with a room's. `scope` is a clause of the behaviour
   * and not of the pack for the same reason `priority` and `slots` are: one pack may carry both
   * kinds, and a pack-level clause could not say which of its behaviours the word applies to.
   */
  scope?: "room" | "house";
  /**
   * The services this behaviour may call, as `domain.service`. The set is the behaviour's
   * declaration of permissions and not a comment on them: the sandbox refuses a call the
   * behaviour's own clause omits, and the pack's effective permission set is computed from
   * these clauses rather than written a second time by hand, so the declaration cannot disagree
   * with the behaviours it describes.
   */
  services?: string[];
  /**
   * The pack-declared slots this behaviour reaches entities through. A clause of the behaviour
   * rather than of the pack, because a pack that declares two slots cannot otherwise say which
   * one a behaviour reads: the sandbox admits a command only through a slot the command's own
   * behaviour names, and a physical button's press is reached the same way rather than through
   * whichever slot the engine happened to visit.
   */
  slots?: string[];
  /**
   * The packs this behaviour holds off while it is on: the module-level override one pack is
   * allowed to place over another, and nothing more. This is the first clause in the manifest
   * that reaches outside the declaring pack -- every other one configures the pack itself --
   * and what it reaches is the whole of the target's module switch. Deliberately packs and not
   * behaviours, settings or slots: what a suppression does is switch a module off, the one act
   * that changes nothing about the target and is therefore the one act installation can always
   * undo, and a clause that reached further would be a pack editing another pack's
   * configuration -- a state no uninstall can restore and no person can see. Deliberately a
   * declaration and not a log: the manifest says which packs *this* behaviour would hold off,
   * and which of those it is actually holding off right now is derived from which modules are
   * on, which is why suppression is temporary by construction and cannot outlive the switch
   * that caused it. The target need not exist in any particular house -- a manifest does not
   * know which house it will land in -- so a pack may name one it expects beside it, and a
   * house without it simply has nothing held off. A pack naming itself is refused when the
   * manifest is validated: the suppression is derived from what is on, so a pack holding itself
   * off would go off the instant it was on and come back the instant it was off, a module that
   * can never run with no switch anywhere that explains what a person is seeing. Omitted means
   * the behaviour suppresses nothing, which is every 1.3.0 pack and most of 1.4.0.
   */
  suppresses?: string[];
  /** A trigger block kind, resolved against the published vocabulary rather than restated here. */
  trigger?: BehaviourVocabularyTrigger;
}

export interface PackManifestDeclaredSlot {
  /** Home Assistant domains a binding for this slot may use. */
  accepts_domains: string[];
  /**
   * The slot's name. A name the slot vocabulary already carries *reuses* that slot: the pack is
   * asking for the same device every other pack asking for it gets, which is the default. A
   * name the vocabulary does not carry is a slot this pack introduces, and it joins the house's
   * vocabulary when the pack is installed.
   */
  name: string;
  /**
   * True when a behaviour of this pack cannot run without it. Ignored for a name the catalog
   * already carries: that slot's own `required` is the catalog's answer and not a pack's.
   */
  required?: boolean;
  /**
   * True when this pack wants a device of its own rather than the one every pack naming the
   * slot shares. A separate slot is bound under a pack-qualified key, so two packs may each
   * hold their own motion sensor while a third shares the room's.
   */
  separate?: boolean;
}

export interface PackManifestI18n {
  /**
   * One default string per user-visible name the pack declares: the pack's own name and
   * description, and each declared behaviour's name. The schema requires the block and its
   * non-emptiness; that the keys cover every declared name is checked against the manifest's
   * own `behaviours`, because a static schema cannot name the keys a document will declare.
   */
  default: { [key: string]: string; };
  /**
   * Per-locale overrides, resolved over the default: a locale with no override reads the
   * default, and an override for a string whose default is absent is refused, because an
   * override is a replacement for something and a replacement with nothing behind it is a
   * string that disappears in every other locale.
   */
  locales?: { [key: string]: PackManifestI18nOverrides; };
}

export type PackManifestI18nOverrides = { [key: string]: string; };

export interface PackManifestOption {
  /**
   * The value when no layer sets one, and so the bottom of the resolver's stack for this key.
   * Its JSON type is checked against `type` when the manifest is validated rather than here,
   * because a static schema cannot compare one property to another: a `duration`'s default is a
   * whole number of seconds, an `integer`'s a whole number, a `boolean`'s `true` or `false`, an
   * `enum`'s one of its own members.
   */
  default: unknown;
  /**
   * The sentence under the title that says what changing it *does*, for when the title is not
   * enough. Optional, because a good title often is enough and a required field would collect
   * filler.
   */
  description?: string;
  /**
   * The members a `type: enum` option may take, and required for it -- an enum with no members
   * admits no value at all. Refused on every other type when the manifest is validated, because
   * a member list beside a `boolean` is a clause nobody reads and everybody copies.
   */
  enum?: string[];
  /**
   * The option's name, and the last segment of the setting it resolves under: an option `key:
   * open_minutes` in pack `fridge_guard` is the config key `module.fridge_guard.open_minutes`.
   * The same shape every slot and behaviour name takes, so one name grammar covers the manifest
   * rather than three.
   */
  key: string;
  /**
   * The highest value a `number`, `integer` or `duration` may take, with the same two meanings
   * `minimum` has. Absent means unbounded above.
   */
  maximum?: number;
  /**
   * The lowest value a `number`, `integer` or `duration` may take, checked when the manifest is
   * validated and applied to the control the panel draws. Absent means unbounded below.
   */
  minimum?: number;
  /**
   * The one line a person reads beside the control -- "How long the door may stay open" --
   * written for somebody who has never opened the manifest. Required, because an option whose
   * only name is its `key` is an option the panel can only label `open_minutes`, which is the
   * defect the whole clause exists to fix.
   */
  title: string;
  /**
   * What kind of value the option takes, which is what decides the control the panel draws: a
   * checkbox for `boolean`, a number field for `integer` and `number`, a select for `enum`, a
   * text field for `string`, and a number field read as a length of time for `duration`. The
   * set is closed rather than the JSON Schema type union, because a control has to be chosen
   * for each and a type outside this list is a control nothing draws. `duration` is `integer`
   * seconds with a unit shown beside it -- a person sets *how long*, and the engine's one use
   * for a duration (`for`) reads it in seconds without parsing a string.
   */
  type: "boolean" | "integer" | "number" | "string" | "enum" | "duration";
  /**
   * The unit shown beside the control for a `number` or `integer` -- `minutes`, `°C`, `%`.
   * Display only, and never parsed: a `duration` is always seconds and says so in its own type
   * rather than through this field, which is what keeps one unit string from meaning a
   * multiplier in one place and a label in another.
   */
  unit?: string;
}

export interface PackManifestProvided {
  /**
   * The artifact class this entry confers, drawn from the closed class set rather than from
   * free text. `mode` is 1.2.0's one addition to 1.1.0's ten, and the ten are unchanged and in
   * their published order: a class removed would invalidate every pack that pinned it. The file
   * an entry pins must be of the class it declares -- a file of class `mode` validates against
   * `schemas/mode/1.0.0.json` -- which is what stops a pack conferring an artifact of a class
   * it did not name. `profile` is deliberately absent: what it would pin is the whole-house
   * bundle `schemas/profile/1.0.0.json` fixes, and this phase ships the state a behaviour is
   * gated on rather than the bundle that activates it.
   */
  class: "package" | "automation" | "script" | "scene" | "helper" | "template" | "blueprint" | "dashboard" | "custom_integration" | "other" | "mode";
  /**
   * Repo-relative path. A string fact, so its shape comes from
   * `schemas/catalog/fact-shapes.yaml` shared by every filed fact. Resolved against the
   * repository root and required to stay inside the pack's own directory -- resolving against
   * the root is only sound if the answer is still inside the pack.
   */
  path: string;
}

export interface PackManifestReference {
  name: string;
  /**
   * The same semver range grammar `engine_api` takes, so a pack author has one range syntax and
   * not two.
   */
  range: string;
}

// ----------------------------------------------------------------------
// profile @ 1.2.0
// ----------------------------------------------------------------------
export interface Profile {
  /**
   * The dimension a room profile governs -- lighting, climate, media. Two active profiles in
   * one room must differ in axis, which is what makes simultaneity a property of the data
   * rather than a rule a caller remembers. Required for `room` and forbidden for `house`.
   */
  axis?: string;
  /**
   * The settings this profile changes, as config keys to values. A room profile's deltas apply
   * in the room it is selected in; a house profile's apply at house scope. A delta is over the
   * room's (or house's) base, so a key absent here takes the base's value. Applying a profile's
   * deltas leaves it in force: the key it names reads as the profile says until the profile is
   * taken off, which is what a *hand-written* profile is for. A profile taken from a house
   * carries `setup` instead.
   */
  deltas?: { [key: string]: unknown; };
  description: string;
  /**
   * Behaviour ids this profile enables, resolved through the same enable key the engine gates a
   * unit on.
   */
  enabled_behaviours?: string[];
  /**
   * A `room` profile is selected in a room and applies its deltas there; a `house` profile
   * bundles the room selections the whole house takes at once, and is the only kind that can be
   * taken from a house.
   */
  kind: "room" | "house";
  /** Mode names this profile activates. */
  modes?: string[];
  name: string;
  /**
   * A house profile's room selections: room id to axis to the room profile selected on that
   * axis. Selecting a house profile sets exactly these. A taken profile carries the selections
   * the house was on, and they apply the way a written profile's do -- a selection is a fact
   * about which profile a room is on, not a setting, and the layer it resolves at is the same
   * either way.
   */
  selections?: { [key: string]: { [key: string]: string; }; };
  /**
   * A *taken* house profile's house: everything the house was configured to be at the moment
   * the profile was taken. Its presence is what makes a house profile a snapshot, and applying
   * it writes each part back where a person's own edit of that part would have been written.
   * Absent parts are not an omission to be filled in from the current house -- a house that had
   * no modules hosted had none, and restoring is putting the house back rather than merging
   * into it. `additionalProperties` is true because these are the house's own documents, whose
   * shapes the things that own them define (`LiveSession.to_state`,
   * `ha_adapter/module_records.py`) and this schema does not restate: a copy restated here
   * would be a second definition of a house, drifting from the first the moment either changed.
   */
  setup?: { [key: string]: unknown; };
}

export type ProfileEnabledBehaviour = string;

export type ProfileMode = string;

// ----------------------------------------------------------------------
// room-type @ 1.0.0
// ----------------------------------------------------------------------
export interface RoomType {
  /**
   * True when Phase 1 may pre-populate this type for a new user. A `default: true` type must
   * trace to source rooms in at least two different repos: this is a quality gate on what we
   * assume on a stranger's behalf, not a coverage rule.
   */
  default: boolean;
  description?: string;
  name: string;
  /** Slot names this type provides. Scope checking reads this. */
  provides_slots: string[];
  source_rooms: RoomTypeSourceRoom[];
}

export type RoomTypeProvidesSlot = string;

export interface RoomTypeSourceRoom {
  path?: string;
  repo: string;
  room: string;
}

// ----------------------------------------------------------------------
// scenario @ 1.0.0
// ----------------------------------------------------------------------
export interface Scenario {
  /** What the scenario is for, in the author's words. Read by a human and carried nowhere else. */
  description?: string;
  given: ScenarioGiven;
  /**
   * What the run is called in a failure report. Optional: the scenario's path is the name when
   * this is absent, and a corpus file rarely needs both.
   */
  name?: string;
  /**
   * The assertions, in order. At least one, because a scenario that asserts nothing is a green
   * run that proves nothing.
   */
  then: ScenarioAssertion[];
  /**
   * The steps, in order. Empty is permitted and meaningful: a scenario that only asserts the
   * house it just built is how the OFF-by-default rule is checked.
   */
  when: ScenarioStep[];
}

export interface ScenarioAssertion {
  attribute?: ScenarioAttributeAssertion;
  availability?: ScenarioAvailabilityAssertion;
  log?: ScenarioLogAssertion;
  state?: ScenarioStateAssertion;
}

export interface ScenarioAttributeAssertion {
  entity_id: string;
  /** The value the attribute is expected to hold. */
  is: unknown;
  name: string;
}

export interface ScenarioAvailabilityAssertion {
  entity_id: string;
  /** Whether the device is expected to answer. */
  is: boolean;
}

export interface ScenarioCommand {
  action?: string;
  entities?: string[];
  origin?: "user" | "engine" | "world" | "fault";
  slot?: string;
}

export type ScenarioDocumentRef = unknown;

export interface ScenarioGiven {
  /**
   * Settings set before the first step, keyed as the resolver keys them --
   * behaviour.<id>.enabled. The house layer, so a scenario can turn a behaviour on without a
   * control-surface operation that enables one.
   */
  enable_flags?: { [key: string]: unknown; };
  /**
   * A fixture's name -- minimal, messy, large or no_lux -- or an inline house document
   * validating against schemas/house/1.0.0.json. Either way the house is built through the fake
   * adapter's own operations and is never loaded as a baked snapshot.
   */
  house: unknown;
  /** The random stream's seed. Defaults to the fixture's own when absent. */
  seed?: number;
  /**
   * The virtual instant the session opens at, as an ISO 8601 timestamp with an offset. Defaults
   * to the fixture's own when absent. The engine never reads the wall clock, so this is the
   * only 'when' a run has.
   */
  started_at?: string;
}

export interface ScenarioInput {
  active?: boolean;
  awaited?: string[];
  empty?: boolean;
  entities?: string[];
  entity_id?: string;
  key?: string;
  kind?: "read" | "setting" | "dark_source" | "mode" | "presence" | "override";
  layer?: "builtin" | "house" | "room" | "profile" | "override";
  mode?: string;
  quiet_rooms?: string[];
  reduction?: "any" | "all";
  released?: null;
  slot?: string;
  source?: "lux" | "sun";
  value?: unknown;
}

export interface ScenarioLogAssertion {
  because?: ScenarioRecord;
  must?: ScenarioRecord[];
  must_not?: ScenarioRecord[];
}

export interface ScenarioRecord {
  actor?: string;
  commands?: ScenarioCommand[];
  /**
   * Inputs the record must carry. Each matcher must match one of the record's inputs, and the
   * order is not constrained.
   */
  inputs?: ScenarioInput[];
  outcome?: "acted" | "declined" | "lost arbitration" | "overridden" | "rate-limited" | "skipped: unbound slot" | "skipped: disabled" | "refused: unsafe";
  rule?: null;
  state_delta?: ScenarioStateChange[];
}

export interface ScenarioStateAssertion {
  entity_id: string;
  /** The state the entity is expected to read. */
  is: string;
}

export interface ScenarioStateChange {
  after?: string;
  before?: string;
  entity_id?: string;
}

export interface ScenarioStep {
  add_entity?: { attributes?: { [key: string]: unknown; }; entity_id: string; state: string; };
  advance_time?: { minutes: number; };
  /** The export_config operation, plus `save` naming the document for a later import_config. */
  export_config?: { save?: string; };
  get_decision_log?: { window?: number; };
  import_config?: { document: ScenarioDocumentRef; };
  inject_fault?: { entity_id: string; fault: string; };
  install_pack?: { manifest: string; };
  remove_entity?: { entity_id: string; };
  restart?: Record<string, never>;
  restore?: { document: ScenarioDocumentRef; };
  set_availability?: { available: boolean; entity_id: string; };
  set_state?: { entity_id: string; state: string; };
  /**
   * The snapshot operation, which takes no parameters, plus the runner's own bookkeeping:
   * `save` names the returned document so a later step can restore it. The name is where the
   * runner keeps the result, not an argument the operation receives.
   */
  snapshot?: { save?: string; };
  user_action?: { entity_id: string; state: string; };
}

// ----------------------------------------------------------------------
// slot @ 1.0.0
// ----------------------------------------------------------------------
export interface Slot {
  /** Home Assistant domains a binding may use, e.g. `light`. */
  accepts_domains: string[];
  description?: string;
  /** At least one, and at least two different repos when source_repos has more than one. */
  examples: SlotExample[];
  /** Controlled-vocabulary name, lower snake case. */
  name: string;
  /** True when a room of a type providing this slot cannot be set up without it. */
  required: boolean;
  /** Every repo whose usage produced this slot. */
  source_repos: string[];
}

export type SlotAcceptsDomain = string;

export type SlotSourceRepo = string;

export interface SlotExample {
  /**
   * Our own words. Required when raw_ids is empty, and required in place of an entity reference
   * when the source does not grant reuse.
   */
  description?: string;
  /** Raw records this example was drawn from. Empty is permitted, but only with a description. */
  raw_ids?: string[];
  repo: string;
  /** Copied from the licence record so the example is auditable without a join. */
  reuse_status_code: "reusable" | "ideas_only";
}
